func filter(in <-chan string, keep func(string) bool) <-chan string {
    out := make(chan string)
    go func() {
        defer close(out)                  // EOF for the next stage
        for rec := range in {
            if keep(rec) { out <- rec }
        }
    }()
    return out
}
// src -> filter(src, valid) -> sink

